RAW = ['company','domain','alt_domain','city','state','confidence','gate_flag','research_note']

def write(path, rows):
    out = []
    for r in rows:
        d = dict(zip(RAW, r))
        code = d['state']
        sub = SUBDIVISION.get(d['company'])
        if sub:                       # code is a state or province
            d['country'] = sub
        elif code == 'US':            # already a country, no subdivision known
            d['country'], d['state'] = 'US', ''
        else:                         # code is an ISO country code, or blank
            d['country'], d['state'] = code, ''
        out.append(d)
    with open(path,'w',newline='',encoding='utf-8-sig') as f:
        w = csv.DictWriter(f, fieldnames=COLS, quoting=csv.QUOTE_ALL)
        w.writeheader(); w.writerows(out)
    bad = [d['company'] for d in out if not d['country']]
    print(f'{path}: {len(out)} rows' + (f'  ({len(bad)} with no country: {bad})' if bad else ''))

write('heimtextil_domains.csv', HEIMTEXTIL)
write('tise_domains.csv', TISE)
write('coverings_domains.csv', COVERINGS)
